const b = $('Webhook').first().json.body || {};
const periodo = String(b.periodo || new Date().toISOString().slice(0, 7));

const tx  = $('Leggi Transazioni').all().map(i => i.json);
const cat = $('Leggi Categorie').all().map(i => i.json).filter(c => c.categoria);

const budget = {};
const tipoDi = {};
cat.forEach(c => {
  budget[c.categoria] = Number(c.budget_mensile) || 0;
  tipoDi[c.categoria] = String(c.tipo || 'spesa').toLowerCase();
});

const arr = n => Math.round(n * 100) / 100;

let entrate = 0, uscite = 0, daVerificare = 0;
const perCat = {};

// startsWith copre giorno, mese e anno con lo stesso codice: e' il motivo
// per cui le date sono in formato ISO.
tx.forEach(r => {
  if (!String(r.data_evento).startsWith(periodo)) return;
  if (String(r.stato) === 'eliminata' || String(r.stato) === 'attesa') return;

  const imp  = Number(r.importo) || 0;
  const tipo = String(r.tipo);
  console.log(r.data_evento,r.importo);
  if (tipo === 'entrata') entrate += imp;
  else if (tipo === 'spesa') uscite += imp;
  else return;                                  // i giroconti non contano

  if (String(r.stato) === 'da_verificare') daVerificare++;

  const c = String(r.categoria || 'Senza categoria');
  perCat[c] = (perCat[c] || 0) + imp;
});

// Il budget nel foglio e' mensile: va scalato al periodo richiesto.
// Su un singolo giorno non ha senso, quindi niente barra.
const mult = periodo.length === 4 ? 12 : periodo.length === 7 ? 1 : 0;

const categorie = Object.keys(perCat)
  .map(nome => ({
    nome,
    tipo: tipoDi[nome] || 'spesa',
    speso: arr(perCat[nome]),
    budget: arr((budget[nome] || 0) * mult),
  }))
  .sort((a, b2) => b2.speso - a.speso);

// Attese ancora aperte, indipendenti dal periodo scelto: quello che sta per
// uscire interessa sempre, anche guardando un mese passato.
const attese = tx
  .filter(r => String(r.stato) === 'attesa' && r.data_evento)
  .sort((a, b) => String(a.data_evento).localeCompare(String(b.data_evento)))
  .map(r => ({
    hash: String(r.hash_dedup || ''),
    data: String(r.data_evento),
    tipo: String(r.tipo || 'spesa'),
    importo: Number(r.importo) || 0,
    etichetta: String(r.esercente || r.note || ''),
    categoria: String(r.categoria || ''),
  }));

const attese_totale = arr(attese.reduce((s, a) => s + a.importo, 0));

return [{ json: {
  periodo,
  entrate: arr(entrate),
  uscite: arr(uscite),
  saldo: arr(entrate - uscite),
  da_verificare: daVerificare,
  categorie,
  attese,
  attese_totale,
  config: {
    categorie_spesa:   cat.filter(c => tipoDi[c.categoria] === 'spesa').map(c => c.categoria),
    categorie_entrata: cat.filter(c => tipoDi[c.categoria] === 'entrata').map(c => c.categoria),
    conti: ['banca', 'contante', 'paypal', 'satispay', 'revolut'],
  },
}}];

const b = $('Webhook').first().json.body || {};
const periodo   = String(b.periodo || new Date().toISOString().slice(0, 7));
const filtroCat = b.categoria ? String(b.categoria) : null;
const soloDaVer = b.solo_da_verificare === true;

const movimenti = $('Leggi Transazioni1').all().map(i => i.json)
  .filter(r => !filtroCat || String(r.categoria) === filtroCat)
  .filter(r => !soloDaVer || String(r.stato) === 'da_verificare')
  .sort((a, b2) => String(b2.data_evento).localeCompare(String(a.data_evento)))
  // Solo i campi che servono all'app: testo_grezzo puo' essere lungo
  // migliaia di caratteri e moltiplicato per 800 righe affossa la risposta.
  .map(r => ({
    hash:      String(r.hash_dedup || ''),
    data:      String(r.data_evento || ''),
    importo:   Number(r.importo) || 0,
    tipo:      String(r.tipo || 'spesa'),
    etichetta: String(r.esercente || r.note || ''),
    categoria: String(r.categoria || ''),
    conto:     String(r.conto || ''),
    fonte:     String(r.fonte || ''),
    stato:     String(r.stato || ''),
  }));

return [{ json: { periodo, movimenti } }];

function normalizza(s) {
  if (!s) return '';
  return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

function hash64(str) {
  let h = 0xcbf29ce484222325n;
  const p = 0x100000001b3n;
  for (let i = 0; i < str.length; i++) {
    h ^= BigInt(str.charCodeAt(i));
    h = (h * p) & 0xffffffffffffffffn;
  }
  return h.toString(16).padStart(16, '0');
}

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const b = $('Webhook').first().json.body || {};

const importo = Number(b.importo);
if (!importo || importo <= 0 || !isFinite(importo)) {
  return [{ json: { valido: false, errore: 'importo non valido' } }];
}

const tipo = b.tipo === 'entrata' ? 'entrata' : 'spesa';
if (!b.categoria) {
  return [{ json: { valido: false, errore: 'categoria mancante' } }];
}

const data      = String(b.data || new Date().toISOString().slice(0, 10)).slice(0, 10);
const esercente = normalizza(b.esercente || '');
const conto     = String(b.conto || 'banca');
const adesso    = new Date().toISOString();

// L'ultimo elemento fa le veci dell'id_esterno che nelle altre fonti
// identifica il messaggio. Qui non c'e', e il timestamp garantisce che due
// inserimenti volutamente identici restino distinti.
const hash = hash64([data, importo.toFixed(2), esercente, conto,
                     'app_' + Date.now()].join('|'));

// Stessa logica di deduplica della pipeline, ma NON scarta: l'utente ha
// deciso lui di inserirla. Al massimo lo avvisa.
const minuti = (x, y) =>
  Math.abs(new Date(x).getTime() - new Date(y).getTime()) / 60000;

const simile = $('Leggi Transazioni2').all().map(i => i.json).some(r =>
  Number(r.importo) === importo &&
  String(r.conto) === conto &&
  r.data_inserimento &&
  minuti(r.data_inserimento, adesso) <= 360
);

return [{ json: {
  valido: true,
  duplicato_sospetto: simile,
  riga: {
    id: uuid(),
    data_evento: data,
    data_inserimento: adesso,
    fonte: 'app',
    tipo,
    importo: importo.toFixed(2),
    valuta: 'EUR',
    conto,
    esercente,
    categoria: String(b.categoria),
    sottocategoria: '',
    note: String(b.note || ''),
    testo_grezzo: 'inserimento manuale da app',
    hash_dedup: hash,
    confidenza: '1.00',
    stato: 'confermata',
  },
}}];

const p = $('Prepara inserimento').first().json;
return [{ json: {
  ok: true,
  hash: p.riga.hash_dedup,
  duplicato_sospetto: p.duplicato_sospetto,
}}];

const b = $('Webhook').first().json.body || {};

if (!b.hash)      return [{ json: { ok: false, errore: 'hash mancante' } }];
if (!b.categoria) return [{ json: { ok: false, errore: 'categoria mancante' } }];

const imp = Number(b.importo);
if (!imp || imp <= 0 || !isFinite(imp)) {
  return [{ json: { ok: false, errore: 'importo non valido' } }];
}

return [{ json: {
  hash: String(b.hash),
  categoria: String(b.categoria),
  stato: String(b.stato || 'confermata'),
  importo: imp.toFixed(2),
}}];

const b = $('Webhook').first().json.body || {};
const valori = b.valori || {};

const valide = new Set(
  $('Leggi Categorie2').all().map(i => String(i.json.categoria)).filter(Boolean)
);

// Solo categorie che esistono davvero: un nome sbagliato creerebbe righe
// fantasma o aggiornerebbe la riga sbagliata.
const items = Object.keys(valori)
  .filter(c => valide.has(c))
  .map(c => ({ json: {
    categoria: c,
    budget_mensile: Number(valori[c]) || 0,
  }}));

if (!items.length) return [{ json: { categoria: '', budget_mensile: 0 } }];
return items;

const b = $('Webhook').first().json.body || {};
if (!b.hash) return [{ json: { ok: false, errore: 'hash mancante' } }];
return [{ json: { hash: String(b.hash), stato: 'eliminata' } }];

const b = $('Webhook').first().json.body || {};
const filtroCat = b.categoria ? String(b.categoria) : null;

const tutte = [
  ...$('Leggi Transazioni3').all().map(i => i.json),]

const oggi = new Date();
const mesi = [];
for (let k = 12; k >= 0; k--) {
  const d = new Date(oggi.getFullYear(), oggi.getMonth() - k, 1);
  mesi.push(d.toISOString().slice(0, 7));
}

const arr = n => Math.round(n * 100) / 100;

const serie = mesi.map(mese => {
  const righe = tutte.filter(r =>
    String(r.data_evento).startsWith(mese) &&
    (!filtroCat || String(r.categoria) === filtroCat));
  const s = (t) => righe.filter(r => String(r.tipo) === t)
                        .reduce((x, r) => x + (Number(r.importo) || 0), 0);
  return { mese, uscite: arr(s('spesa')), entrate: arr(s('entrata')) };
});

// La media esclude il mese in corso, che è parziale e abbasserebbe il
// riferimento proprio quando serve confrontarcisi.
const conclusi = serie.slice(0, -1);
const media_uscite = arr(
  conclusi.reduce((s, m) => s + m.uscite, 0) / (conclusi.length || 1));

return [{ json: { mesi: serie, media_uscite, categoria: filtroCat } }];

const a = $('Webhook').first().json.body?.azione;
return [{ json: {
  ok: false,
  errore: 'azione sconosciuta: ' + (a || '(vuota)'),
}}];
